expected$::jsonb j),
ef as (select * from jsonb_to_recordset((select j->'functions' from expected)) as x(name text,body text,body_raw text,definer boolean,volatility text,types text,names jsonb,returns text)),
ep as (select * from jsonb_to_recordset((select j->'policies' from expected)) as x(name text,schema text,"table" text,permissive boolean,cmd text,roles jsonb,falseguard boolean,helper text,"using" text,"check" text)),
af as (select p.*,n.nspname, md5(trim(regexp_replace(p.prosrc,'\s+',' ','g'))) body_hash from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f'),
checks as (
 select 'EXECUTION_CONTEXT' check_name, current_user='postgres' ok, 'Run in original project owner SQL Editor; verify Dashboard reference privately.' action
 union all
 select 'FUNCTION_'||e.name, count(a.oid)=1 and bool_and((case when e.body_raw is not null then md5(a.prosrc)=e.body_raw else a.body_hash=e.body end) and a.prosecdef=e.definer and a.provolatile::text=e.volatility and oidvectortypes(a.proargtypes)=e.types and to_jsonb(coalesce(a.proargnames,array[]::text[]))=e.names and format_type(a.prorettype,null)=e.returns), 'Missing, overloaded or changed release function. Review its body/signature/security before replacement.' from ef e left join af a on a.proname=e.name group by e.name
 union all
 select 'FUNCTION_SEARCH_PATH_'||e.name, coalesce(bool_and(a.proconfig @> array['search_path=""']),false), 'Security-definer helper must retain empty search_path.' from ef e left join af a on a.proname=e.name where e.definer and e.name<>'handle_updated_at' group by e.name
 union all
 select 'NEW_OBJECT_COLLISION_'||x.name, not exists(select 1 from af where proname=x.name) and to_regclass('public.'||x.name) is null, '015 expects a new object; inspect partial/prior deployment instead of replaying.' from expected,jsonb_array_elements_text(j->'new') x(name)
 union all
 select 'POLICY_'||e.schema||'.'||e."table"||'.'||e.name,
 coalesce(p.polpermissive=e.permissive and p.polcmd::text=e.cmd and
 (select jsonb_agg(r.role_name order by r.role_name) from (select case when rid=0 then 'public' else pg_get_userbyid(rid) end role_name from unnest(p.polroles) rid) r)=e.roles
 and coalesce(pg_get_expr(p.polqual,p.polrelid),'')=e."using" and coalesce(pg_get_expr(p.polwithcheck,p.polrelid),'')=e."check"
 and (not e.falseguard or coalesce(pg_get_expr(p.polqual,p.polrelid),'')='false' or coalesce(pg_get_expr(p.polwithcheck,p.polrelid),'')='false')
 and (e.helper='' or position(e.helper in coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''))>0),false),
 'Missing/changed policy command, role, restrictive guard or authorization dependency; review full expression privately.'
 from ep e left join pg_namespace n on n.nspname=e.schema left join pg_class c on c.relnamespace=n.oid and c.relname=e."table" left join pg_policy p on p.polrelid=c.oid and p.polname=e.name
 union all
 select 'RLS_'||e.schema||'.'||e."table", coalesce(c.relrowsecurity,false), 'Required application/Storage table missing or RLS disabled.' from (select distinct schema,"table" from ep union select 'public','nigraan_incident_workflow_events' union select 'public','nigraan_operations_public_updates')e left join pg_namespace n on n.nspname=e.schema left join pg_class c on c.relnamespace=n.oid and c.relname=e."table"
 union all
 select 'UNKNOWN_PUBLIC_FUNCTION_'||a.proname,false,'Unreviewed function: inspect authorization and effects privately; do not waive by name.' from af a where not exists(select 1 from ef where name=a.proname) and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=a.oid and d.deptype='e')
 union all
 select 'UNKNOWN_POLICY_'||n.nspname||'.'||c.relname||'.'||p.polname,false,'Unreviewed policy: inspect complete authorization expression privately.' from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where (n.nspname='public' or (n.nspname='storage' and c.relname='objects')) and not exists(select 1 from ep where schema=n.nspname and "table"=c.relname and name=p.polname)
 union all
 select 'NEW_TRIGGER_COLLISIONS',not exists(select 1 from pg_trigger where tgname in ('nigraan_expiring_workflow_write','nigraan_expiring_public_update')),'New trigger name already exists; stop for partial deployment review.'
 union all
 select 'WORKFLOW_TRIGGER',exists(select 1 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid where n.nspname='public' and c.relname='incidents' and t.tgname='nigraan_workflow_after_change' and t.tgenabled='O' and t.tgtype=21 and p.proname='nigraan_record_workflow'),'Expected enabled AFTER INSERT OR UPDATE row workflow trigger is missing/changed.'
 union all
 select 'RULE_'||n.nspname||'.'||c.relname||'.'||r.rulename,false,'Unreviewed rewrite rule can redirect writes; inspect before rollout.' from pg_rewrite r join pg_class c on c.oid=r.ev_class join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p')
 union all
 select 'MIGRATION_HISTORY_SOURCE',to_regclass('supabase_migrations.schema_migrations') is not null,'Migration history unavailable. Reconcile privately with reviewed definitions; do not replay historical SQL.'


 union all
 select 'COLUMN_'||e.tbl||'.'||e.col, coalesce((format_type(a.atttypid,a.atttypmod)=e.typ or (e.tbl='auth.users' and e.col='email' and a.atttypid in ('text'::regtype,'character varying'::regtype))),false), 'Missing/incompatible required column. Review actual type before 015.' from (values ('public.profiles','id','uuid'),('public.operations_profiles','user_id','uuid'),('public.operations_profiles','organization_name','text'),('public.operations_profiles','organization_type','text'),('public.operations_profiles','verification_status','text'),('public.incidents','id','uuid'),('public.incidents','reporter_id','uuid'),('public.incidents','status','text'),('public.incidents','submission_state','text'),('public.incidents','assigned_organization_id','uuid'),('public.evidence','id','uuid'),('public.evidence','incident_id','uuid'),('public.evidence','uploader_id','uuid'),('public.evidence','storage_path','text'),('public.evidence','mime_type','text'),('public.evidence','file_size','integer'),('public.nigraan_citizen_changes','id','uuid'),('public.nigraan_citizen_changes','incident_id','uuid'),('public.nigraan_citizen_changes','citizen_id','uuid'),('public.nigraan_citizen_changes','submission_state','text'),('public.nigraan_incident_workflow_events','incident_id','uuid'),('public.nigraan_incident_workflow_events','kind','text'),('public.nigraan_incident_workflow_events','previous_status','text'),('public.nigraan_incident_workflow_events','status','text'),('public.nigraan_incident_workflow_events','actor_id','uuid'),('public.nigraan_operations_public_updates','incident_id','uuid'),('public.nigraan_operations_public_updates','author_id','uuid'),('public.nigraan_operations_public_updates','kind','text'),('public.nigraan_operations_public_updates','message','text'),('public.nigraan_operations_public_updates','request_id','uuid'),('auth.users','id','uuid'),('auth.users','email','character varying'),('auth.users','email_confirmed_at','timestamp with time zone'),('storage.objects','name','text'),('storage.objects','bucket_id','text'),('storage.objects','metadata','jsonb')) e(tbl,col,typ) left join pg_attribute a on a.attrelid=to_regclass(e.tbl) and a.attname=e.col and not a.attisdropped
 union all
 select 'PROFILE_PRIMARY_KEY',exists(select 1 from pg_constraint k where k.conrelid=to_regclass('public.profiles') and k.contype in ('p','u') and (select array_agg(a.attname::text order by a.attnum) from pg_attribute a where a.attrelid=k.conrelid and a.attnum=any(k.conkey))=array['id']), 'New judge foreign keys require unique profiles.id.'
 union all
 select 'OPERATIONS_UNIQUE_IDENTITY',exists(select 1 from pg_constraint k where k.conrelid=to_regclass('public.operations_profiles') and k.contype in ('p','u') and (select array_agg(a.attname::text order by a.attnum) from pg_attribute a where a.attrelid=k.conrelid and a.attnum=any(k.conkey))=array['user_id']), 'Judge approval ON CONFLICT requires unique Operations user_id.'
 union all
 select 'TRIGGER_'||e.schema||'.'||e."table"||'.'||e.name, coalesce(t.tgtype=e.bits and t.tgenabled='O' and fn.proname=e."function",false), 'Expected release trigger missing/changed/disabled.' from expected,jsonb_to_recordset(j->'triggers') e(name text,schema text,"table" text,bits integer,"function" text) left join pg_namespace n on n.nspname=e.schema left join pg_class c on c.relnamespace=n.oid and c.relname=e."table" left join pg_trigger t on t.tgrelid=c.oid and t.tgname=e.name left join pg_proc fn on fn.oid=t.tgfoid
 union all
 select 'UNREVIEWED_TRIGGER_'||n.nspname||'.'||c.relname||'.'||t.tgname,false,'Additional trigger may affect approval/workflow/evidence. Review its function privately.' from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname='public' and c.relname in ('profiles','operations_profiles','incidents','evidence','nigraan_citizen_changes','nigraan_operations_public_updates','nigraan_incident_workflow_events') and not exists(select 1 from expected,jsonb_to_recordset(j->'triggers') e(name text,schema text,"table" text) where e.schema=n.nspname and e."table"=c.relname and e.name=t.tgname)
 union all
 select 'BROWSER_TABLE_WRITES_'||c.relname,not exists(select 1 from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x where x.grantee in (0,(select oid from pg_roles where rolname='anon'),(select oid from pg_roles where rolname='authenticated')) and x.privilege_type in ('INSERT','UPDATE','DELETE','TRUNCATE','TRIGGER')), 'Unexpected browser/public direct write privilege; retain RPC-only workflow.' from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('operations_profiles','incidents','evidence','nigraan_incident_workflow_events','nigraan_operations_public_updates')
 union all
 select 'FUNCTION_PUBLIC_EXECUTE_'||a.proname,not exists(select 1 from aclexplode(coalesce(a.proacl,acldefault('f',a.proowner))) x where x.grantee=0 and x.privilege_type='EXECUTE'),'Unexpected PUBLIC execution on protected function.' from af a join ef e on e.name=a.proname where a.proname<>'handle_updated_at'
 union all
 select 'REQUIRED_ROLES', (select count(*)=3 from pg_roles where rolname in ('anon','authenticated','service_role')), 'Required Supabase roles missing.'
 union all
 select 'DEFAULT_PRIVILEGES_HANDLED_BY_REQUIRED_017',true,'Existing defaults stay unchanged. Apply 017 before enabling requests or worker; postcheck verifies worker-only grants.'
 union all
 select 'AUTH_UID_SIGNATURE',to_regprocedure('auth.uid()') is not null,'Supabase caller identity helper missing.'
 union all
 select 'UNEXPECTED_FK_'||k.conname,false,'Additional FK on a replaced workflow dependency requires private review.' from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where k.contype='f' and n.nspname='public' and c.relname in ('operations_profiles','nigraan_incident_workflow_events','nigraan_operations_public_updates') and k.confrelid not in (coalesce(to_regclass('public.profiles'),0),coalesce(to_regclass('public.incidents'),0),coalesce(to_regclass('public.operations_profiles'),0))


 union all
 select 'UNEXPECTED_REQUIRED_OPERATIONS_COLUMN_'||a.attname,false,'Additional mandatory column without a default can break pending judge identity insertion.' from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=to_regclass('public.operations_profiles') and a.attnum>0 and not a.attisdropped and a.attnotnull and d.oid is null and a.attidentity='' and a.attgenerated='' and a.attname not in ('user_id','organization_name','organization_type','verification_status')
 union all
 select 'OPERATIONS_CHECK_'||k.conname,
 replace(regexp_replace(pg_get_constraintdef(k.oid),'\s|[()]|::text\y','','g'),'public.','') in (
 'CHECKorganization_type=ANYARRAY[''government'',''ngo'',''civic_organization'',''utility'',''volunteer_group'',''other'']',
 'CHECKverification_status=ANYARRAY[''pending'',''approved'',''rejected'']',
 'CHECKlengthTRIMBOTHFROMorganization_name>=1ANDlengthTRIMBOTHFROMorganization_name<=200',
 'CHECKexplanationISNULLORlengthexplanation<=1000NOTVALID',
 'CHECKexplanationISNULLORlengthexplanation<=1000'),
 'Unrecognized Operations CHECK: privately verify it accepts the exact pending judge identity and preserves approval values.' from pg_constraint k where k.conrelid=to_regclass('public.operations_profiles') and k.contype='c'
 union all
 select 'ASSIGNMENT_FK',exists(select 1 from pg_constraint k where k.conrelid=to_regclass('public.incidents') and k.confrelid=to_regclass('public.operations_profiles') and k.contype='f' and k.conkey=array[(select attnum from pg_attribute where attrelid=k.conrelid and attname='assigned_organization_id')]::smallint[] and k.confkey=array[(select attnum from pg_attribute where attrelid=k.confrelid and attname='user_id')]::smallint[]),'Expected assignment-to-Operations identity foreign key missing/changed.'
 union all
 select 'PUBLIC_UPDATE_AUTHOR_FK',exists(select 1 from pg_constraint k where k.conrelid=to_regclass('public.nigraan_operations_public_updates') and k.confrelid=to_regclass('public.operations_profiles') and k.contype='f' and k.conkey=array[(select attnum from pg_attribute where attrelid=k.conrelid and attname='author_id')]::smallint[] and k.confkey=array[(select attnum from pg_attribute where attrelid=k.confrelid and attname='user_id')]::smallint[]),'Expected public-update author foreign key missing/changed.'
 union all
 select 'REPLACEMENT_RETURN_TYPES',not exists(select 1 from af where (proname in ('is_approved_operations','nigraan_storage_access') and prorettype<>'boolean'::regtype) or (proname='nigraan_record_workflow' and prorettype<>'trigger'::regtype)),'CREATE OR REPLACE cannot change an existing return type.'
 union all
 select 'NONPUBLIC_AUTHORIZATION_DEPENDENCY_'||n.nspname||'.'||p.proname,false,'Non-public callable function depends on replaced authorization; review privately.' from pg_depend d join pg_proc p on d.classid='pg_proc'::regclass and p.oid=d.objid join pg_namespace n on n.oid=p.pronamespace join af a on d.refclassid='pg_proc'::regclass and d.refobjid=a.oid where a.proname in ('is_approved_operations','nigraan_storage_access','nigraan_record_workflow') and n.nspname<>'public' and not exists(select 1 from pg_depend ex where ex.classid='pg_proc'::regclass and ex.objid=p.oid and ex.deptype='e')


 union all
 select 'TIMESTAMP_REVIEWED_CONFIG',exists(select 1 from af where proname='handle_updated_at' and pg_get_userbyid(proowner)='postgres'
   and prolang=(select oid from pg_language where lanname='plpgsql') and (coalesce(proconfig,array[]::text[])=array[]::text[] or proconfig=array['search_path=pg_catalog'])), '018 must pin pg_catalog; other config changes require review.'
 union all
 select 'TIMESTAMP_REVIEWED_PRIVILEGES',coalesce((select coalesce(jsonb_agg(jsonb_build_object('role',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable) order by case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable),'[]'::jsonb)=$acl$[{"role":"PUBLIC","grantable":false,"privilege":"EXECUTE"},{"role":"anon","grantable":false,"privilege":"EXECUTE"},{"role":"authenticated","grantable":false,"privilege":"EXECUTE"},{"role":"postgres","grantable":false,"privilege":"EXECUTE"},{"role":"service_role","grantable":false,"privilege":"EXECUTE"}]$acl$::jsonb from af p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))a where p.proname='handle_updated_at'),false),'Timestamp intended grants/owner must not drift.'
 union all
 select 'TIMESTAMP_EXACT_DEPENDENCIES',(select count(*) from pg_trigger t join af p on p.oid=t.tgfoid where p.proname='handle_updated_at')=2 and
   (select count(*) from pg_trigger t join af p on p.oid=t.tgfoid where p.proname='handle_updated_at' and not t.tgisinternal and t.tgtype=19 and t.tgenabled='O' and t.tgattr::text='' and t.tgnargs=0 and t.tgqual is null and t.tgconstraint=0)=2,'Only the two exact reviewed UPDATE triggers are accepted.'
 union all
 select 'NO_NEW_BROWSER_COLUMN_PRIVILEGES',not exists(select 1 from pg_attribute a cross join lateral aclexplode(a.attacl)g where a.attrelid in(to_regclass('public.incidents'),to_regclass('public.evidence'),to_regclass('public.operations_profiles'),to_regclass('public.profiles')) and g.grantee in(0,(select oid from pg_roles where rolname='anon'),(select oid from pg_roles where rolname='authenticated')) and not(g.grantee=(select oid from pg_roles where rolname='authenticated') and a.attrelid=to_regclass('public.profiles') and a.attname in('display_name','phone','avatar_url') and g.privilege_type='UPDATE')),'Legacy compatibility requires exact narrow column grants.'
 union all
 select 'NO_PUBLIC_ANON_TABLE_PRIVILEGES',not exists(select 1 from pg_class c cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner)))g where c.oid in(to_regclass('public.incidents'),to_regclass('public.evidence'),to_regclass('public.operations_profiles'),to_regclass('public.profiles')) and g.grantee in(0,(select oid from pg_roles where rolname='anon'))),'PUBLIC/anon cannot gain access through extra legacy policies.'
 union all
 select 'NO_UNREVIEWED_BROWSER_ROLE_MEMBERSHIP',not exists(select 1 from pg_auth_members where member in(select oid from pg_roles where rolname in('anon','authenticated','service_role'))),'Additional role inheritance requires review.'

),summary as (select coalesce(bool_and(coalesce(ok,false)),false) ok,count(*) filter(where not coalesce(ok,false)) blocked from checks)
select case when s.ok then 'PASS_REQUIRES_015_016_017_018' else 'BLOCKED' end verdict,s.blocked blocked_checks,
 coalesce((select jsonb_agg(jsonb_build_object('check',check_name,'status',case when coalesce(ok,false) then 'PASS' else 'BLOCKED' end,'action',action) order by check_name) from checks where not coalesce(ok,false)),'[]'::jsonb) actionable_mismatches,
 'Catalog-only; manually confirm original Dashboard reference and verified permanent admin. Managed bucket privacy, historical applications and deployed endpoints require separate read-only verification; no automatic deployment approval.' scope
from summary s;
